-- Move current workspaces to monitors (left right up or down)
hl.bind(mainMod .. " + CTRL + F9", function() local w = hl.get_active_workspace(); if not w then return end; hl.dispatch(hl.dsp.workspace.move({ workspace = w.id, monitor = "l" })) end, { description = "move workspace to left monitor" })
hl.bind(mainMod .. " + CTRL + F10", function() local w = hl.get_active_workspace(); if not w then return end; hl.dispatch(hl.dsp.workspace.move({ workspace = w.id, monitor = "r" })) end, { description = "move workspace to right monitor" })
hl.bind(mainMod .. " + CTRL + F11", function() local w = hl.get_active_workspace(); if not w then return end; hl.dispatch(hl.dsp.workspace.move({ workspace = w.id, monitor = "u" })) end, { description = "move workspace to up monitor" })
hl.bind(mainMod .. " + CTRL + F12", function() local w = hl.get_active_workspace(); if not w then return end; hl.dispatch(hl.dsp.workspace.move({ workspace = w.id, monitor = "d" })) end, { description = "move workspace to down monitor" })

